// Unicode normalization utilities for database field processing
namespace unicode {

struct CodePoint {
    uint32_t value;
    uint8_t combining_class;
};

// Canonical decomposition mapping (simplified subset)
static const std::unordered_map<uint32_t, std::vector<uint32_t>> decomposition_map = {
    {0x00C0, {0x0041, 0x0300}},  // À -> A + combining grave
    {0x00C1, {0x0041, 0x0301}},  // Á -> A + combining acute
    {0x00C8, {0x0045, 0x0300}},  // È -> E + combining grave
    {0x00E9, {0x0065, 0x0301}},  // é -> e + combining acute
    {0x01FA, {0x00C1, 0x030A}},  // Ǻ -> Á + combining ring
    {0x2126, {0x03A9}},          // Ω (ohm) -> Ω (omega)
    {0x212B, {0x00C5}},          // Å (angstrom) -> Å
    {0xFF41, {0x0061}},          // ａ (fullwidth) -> a
    {0xFF42, {0x0062}},          // ｂ -> b
    {0xFF43, {0x0063}},          // ｃ -> c
    {0xFF44, {0x0064}},          // ｄ -> d
    {0xFF45, {0x0065}},          // ｅ -> e
    {0xFF4C, {0x006C}},          // ｌ -> l
    {0xFF54, {0x0074}},          // ｔ -> t
    {0xFF52, {0x0072}},          // ｒ -> r
    {0xFF4F, {0x006F}},          // ｏ -> o
    {0xFF50, {0x0070}},          // ｐ -> p
    {0xFF53, {0x0073}},          // ｓ -> s
};

std::vector<uint32_t> nfd_decompose(const std::vector<uint32_t>& input) {
    std::vector<uint32_t> result;
    for (auto cp : input) {
        auto it = decomposition_map.find(cp);
        if (it != decomposition_map.end()) {
            // Recursively decompose
            auto decomposed = nfd_decompose(it->second);
            result.insert(result.end(), decomposed.begin(), decomposed.end());
        } else {
            result.push_back(cp);
        }
    }
    return result;
}

std::vector<uint32_t> utf8_to_codepoints(const std::string& utf8) {
    std::vector<uint32_t> cps;
    size_t i = 0;
    size_t n = utf8.size();
    while (i < n) {
        uint32_t cp = 0;
        unsigned char c = (unsigned char)utf8[i];
        if (c < 0x80) {
            cp = c; i += 1;
        } else if ((c & 0xE0) == 0xC0) {
            if (i + 1 >= n) break; // truncated sequence
            cp = c & 0x1F;
            cp = (cp << 6) | ((unsigned char)utf8[i+1] & 0x3F);
            i += 2;
        } else if ((c & 0xF0) == 0xE0) {
            if (i + 2 >= n) break; // truncated sequence
            cp = c & 0x0F;
            cp = (cp << 6) | ((unsigned char)utf8[i+1] & 0x3F);
            cp = (cp << 6) | ((unsigned char)utf8[i+2] & 0x3F);
            i += 3;
        } else if ((c & 0xF8) == 0xF0) {
            if (i + 3 >= n) break; // truncated sequence
            cp = c & 0x07;
            cp = (cp << 6) | ((unsigned char)utf8[i+1] & 0x3F);
            cp = (cp << 6) | ((unsigned char)utf8[i+2] & 0x3F);
            cp = (cp << 6) | ((unsigned char)utf8[i+3] & 0x3F);
            i += 4;
        } else {
            i += 1; continue;
        }
        cps.push_back(cp);
    }
    return cps;
}

std::string codepoints_to_utf8(const std::vector<uint32_t>& cps) {
    std::string result;
    for (auto cp : cps) {
        if (cp < 0x80) result += (char)cp;
        else if (cp < 0x800) { result += (char)(0xC0 | (cp >> 6)); result += (char)(0x80 | (cp & 0x3F)); }
        else if (cp < 0x10000) { result += (char)(0xE0 | (cp >> 12)); result += (char)(0x80 | ((cp >> 6) & 0x3F)); result += (char)(0x80 | (cp & 0x3F)); }
        else { result += (char)(0xF0 | (cp >> 18)); result += (char)(0x80 | ((cp >> 12) & 0x3F)); result += (char)(0x80 | ((cp >> 6) & 0x3F)); result += (char)(0x80 | (cp & 0x3F)); }
    }
    return result;
}

} // namespace unicode

// Database driver field sanitizer
namespace db_driver {

struct FieldDescriptor {
    std::string name;
    std::string type;  // "text", "identifier", "path"
    size_t max_length;
    bool allow_special;
};

// Security: validate field content against injection patterns
// This runs AFTER normalization to catch attacks that use Unicode equivalents
bool post_normalize_security_check(const std::string& normalized_value, const FieldDescriptor& field) {
    // Block null bytes
    if (normalized_value.find('\0') != std::string::npos) return false;
    // Block SQL metacharacters in identifier fields
    if (field.type == "identifier") {
        for (char c : normalized_value) {
            if (c == '\'' || c == '"' || c == ';' || c == '-' || c == '/' || c == '*') {
                return false;
            }
        }
    }
    // Block path traversal in path fields
    if (field.type == "path") {
        if (normalized_value.find("..") != std::string::npos) return false;
        if (normalized_value.find("//") != std::string::npos) return false;
    }
    return true;
}

// Normalize the field value for consistent storage
std::string normalize_field(const std::string& value) {
    auto cps = unicode::utf8_to_codepoints(value);
    auto decomposed = unicode::nfd_decompose(cps);
    return unicode::codepoints_to_utf8(decomposed);
}

// Length validation
bool validate_length(const std::string& normalized, const FieldDescriptor& field) {
    if (normalized.length() > field.max_length) return false;
    return true;
}

struct QueryParam {
    std::string field_name;
    std::string value;
};

// Escape a value for safe inclusion inside a single-quoted SQL literal.
static std::string escape_sql_literal(const std::string& value) {
    std::string escaped;
    escaped.reserve(value.size());
    for (char c : value) {
        if (c == '\'') {
            escaped += "''"; // double up single quotes
        } else {
            escaped += c;
        }
    }
    return escaped;
}

// Build insert query - escapes field values to prevent SQL injection
std::string build_insert_query(const std::string& table,
                                const std::vector<QueryParam>& params) {
    std::string query = "INSERT INTO " + table + " (";
    std::string values = "VALUES (";
    for (size_t i = 0; i < params.size(); i++) {
        query += params[i].field_name;
        values += "'" + escape_sql_literal(params[i].value) + "'";
        if (i < params.size() - 1) { query += ", "; values += ", "; }
    }
    query += ") " + values + ")";
    return query;
}

// Main entry point for processing uploaded field data
std::string process_upload_field(const std::string& raw_input,
                                  const FieldDescriptor& field) {
    // Step 1: Unicode normalization (decomposition)
    std::string normalized = normalize_field(raw_input);

    // Step 2: Security check AFTER normalization
    if (!post_normalize_security_check(normalized, field)) {
        return "";
    }

    // Step 3: Length validation
    if (!validate_length(normalized, field)) {
        return "";
    }

    return normalized;
}

} // namespace db_driver

int main() {
    // Simulate processing an uploaded CSV with field data
    db_driver::FieldDescriptor name_field{"username", "identifier", 64, false};
    db_driver::FieldDescriptor path_field{"filepath", "path", 256, false};

    // Normal usage
    std::string input1 = "hello_world";
    std::string result1 = db_driver::process_upload_field(input1, name_field);
    std::cout << "Processed: " << result1 << std::endl;

    // Test with accented characters
    std::string input2 = "caf\xC3\xA9";  // café in UTF-8
    std::string result2 = db_driver::process_upload_field(input2, name_field);
    std::cout << "Processed: " << result2 << std::endl;

    return 0;
}
